#include "engine/native_save.hpp"
#include "domain/exterior_water.hpp"
#include "engine/native_population_registry.hpp"
#include <iostream>
using namespace stalthos;using namespace stalthos::fauna;
void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}
int main(){try{std::vector<HabitatSite> sites{{{0,0,24},true,true,{1}},{{12,0,24},true,true,{0}}};Population original(42,1001,sites,8,{1});auto before=original.snapshot();auto habitat=exteriorHabitat(sites,[](double,double){return 0.;},[](double,double){return false;});auto expanded=withExteriorWater(original,habitat,{1},true);auto after=expanded.snapshot();for(std::size_t i=0;i<8;++i)check(before.actors[i].id==after.actors[i].id&&before.actors[i].thirst==after.actors[i].thirst&&before.actors[i].position.x==after.actors[i].position.x,"original8 unchanged");ExteriorWaterSource source;check(source.eligible({132,0,30},0,.04,true),"dry bank eligible");check(!source.eligible({132,3,30},0,.04,true)&&!source.eligible({132,0,30},0,.04,false)&&!source.eligible({160,0,30},0,.04,true),"height support body-bound rejection");std::uint64_t next=1;ResourceLedgerDto ledger{{{100,ResourceKind::Creek,10,0},{200,ResourceKind::Shrub,10,0},{208,ResourceKind::Shrub,1,0},{209,ResourceKind::Creek,2,0}}, {}};std::vector<RegionalResourceAnchor> anchors{{0,100,sites[0].position},{0,200,sites[0].position},{1,100,sites[1].position},{1,200,sites[1].position},{habitat.residents.back(),208,habitat.sites[habitat.residents.back()].position},{habitat.residents[2],209,habitat.sites[habitat.residents[2]].position}};engine::validateNativeResources(ledger,anchors,true);bool oldRejected=false;try{engine::validateNativeResources(ledger,anchors);}catch(const std::runtime_error&){oldRejected=true;}check(oldRejected,"original saved-mode declaration remains unchanged");engine::NativePopulationRegistry host(expanded,ledger,{},anchors,next);host.advance({1,1},true);auto dto=host.ledger().resources.back();check(dto.id==209&&dto.consumedQuantity>0,"resident water contact");double npc=dto.consumedQuantity;const auto session=next++;check(host.consume(session,209,.5)&&!host.consume(session,209,.5),"shared hero contact replay");check(std::abs(host.ledger().resources.back().consumedQuantity-npc-.5)<1e-12,"same finite water ledger");check(host.snapshot().actors[10].thirst<.6,"contact thirst relief");check(host.snapshot().actors.back().hunger<.55,"browse208 preserved");std::cout<<"EXTERIOR_WATER_OK shared contact replay relief support/reach and browse preservation\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
